1	import type { NextRequest } from "next/server";
2	import { ZodError } from "zod";
3	import { endpoints, type EndpointName } from "@/contracts";
4	import { handlers } from "@/mock/handlers";
5	import { ApiError, db } from "@/mock/store";
6	import { backendHandlers } from "@/backend/handlers";
7	import { personaUsers } from "@/backend/personas";
8	
9	/**
10	 * MOCK BACKEND. One catch-all route that implements the REST contract in
11	 * src/contracts/api.ts on the in-memory store. With DATA_SOURCE=backend the
12	 * adapter in src/backend serves the endpoints it implements from the FastAPI
13	 * backend (BACKEND_URL); this mock serves the rest (INTEGRATION-GUIDE.md section 8).
14	 */
15	const USE_BACKEND = process.env.DATA_SOURCE === "backend";
16	
17	const routes = (Object.keys(endpoints) as EndpointName[]).map((name) => {
18	  const def = endpoints[name];
19	  const keys: string[] = [];
20	  const pattern = new RegExp(
21	    "^" +
22	      def.path.replace(/:[a-zA-Z]+/g, (m) => {
23	        keys.push(m.slice(1));
24	        return "([^/]+)";
25	      }) +
26	      "$",
27	  );
28	  return { name, def, keys, pattern };
29	});
30	
31	function match(method: string, path: string) {
32	  for (const r of routes) {
33	    if (r.def.method !== method) continue;
34	    const m = path.match(r.pattern);
35	    if (m) return { ...r, params: Object.fromEntries(r.keys.map((k, i) => [k, decodeURIComponent(m[i + 1])])) };
36	  }
37	  return null;
38	}
39	
40	async function handle(req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) {
41	  const { path } = await ctx.params;
42	  const route = match(req.method, "/" + path.join("/"));
43	  if (!route) return Response.json({ error: `No endpoint ${req.method} /${path.join("/")}` }, { status: 404 });
44	
45	  try {
46	    const userId = req.headers.get("x-user-id") ?? req.cookies.get("rs_user")?.value ?? "u-lena";
47	    const user = (USE_BACKEND ? personaUsers() : db().users).find((u) => u.id === userId);
48	    if (!user) throw new ApiError(401, `Unknown user ${userId}`);
49	
50	    const def = route.def as { query?: { parse(v: unknown): unknown }; body?: { parse(v: unknown): unknown }; response: { safeParse(v: unknown): { success: boolean; error?: ZodError } } };
51	    const query = def.query ? def.query.parse(Object.fromEntries(req.nextUrl.searchParams)) : {};
52	    let body: unknown = undefined;
53	    if (def.body) {
54	      const text = await req.text();
55	      body = def.body.parse(text ? JSON.parse(text) : {});
56	    }
57	
58	    const handler = ((USE_BACKEND && backendHandlers[route.name]) || handlers[route.name]) as (c: unknown) => unknown;
59	    const result = await handler({ params: route.params, query, body, user });
60	
61	    if (process.env.NODE_ENV !== "production") {
62	      const check = def.response.safeParse(result);
63	      if (!check.success) console.error(`[${USE_BACKEND && backendHandlers[route.name] ? "backend" : "mock"}] ${route.name} response breaks the contract:`, check.error?.issues.slice(0, 5));
64	    }
65	    return Response.json(result);
66	  } catch (error) {
67	    if (error instanceof ZodError) return Response.json({ error: "Invalid request", issues: error.issues }, { status: 400 });
68	    if (error instanceof ApiError) return Response.json({ error: error.message }, { status: error.status });
69	    console.error("[mock] unhandled", error);
70	    return Response.json({ error: error instanceof Error ? error.message : "Server error" }, { status: 500 });
71	  }
72	}
73	
74	export { handle as GET, handle as POST, handle as PUT, handle as PATCH, handle as DELETE };
