1	import type { AgentRun, Agent, Notification, QuarantineItem, Signal, TaxonomyResponse, WeightProfile, Workspace, User } from "@/contracts";
2	import type { Handlers } from "@/mock/handlers";
3	import { ApiError } from "@/mock/store";
4	import { backend, cached, invalidateCache, type QueryValue } from "./client";
5	import {
6	  agentFromBackend,
7	  marketFromBackend,
8	  marketToBackend,
9	  powertrainFromBackend,
10	  sourceTypeFromBackend,
11	  trustFromBackend,
12	  weightsFromBackend,
13	  weightsToBackend,
14	} from "./map";
15	import { persona, personaUsers, type Persona } from "./personas";
16	import { resetSidecar, saveSidecar, sidecar, sidecarAudit } from "./sidecar";
17	
18	/**
19	 * Backend-backed handlers (DATA_SOURCE=backend). Same signatures as src/mock/handlers.ts;
20	 * route.ts falls back to the mock for every endpoint not implemented here.
21	 * Endpoint map: INTEGRATION-GUIDE.md section 8 and the wiring plan.
22	 */
23	
24	// ---------- backend row shapes (backend/API.md, /docs) ----------
25	interface BConfig {
26	  id: string;
27	  name: string;
28	  vehicle: string;
29	  market: string;
30	  profiles: { id: string; name: string; is_default: boolean }[];
31	}
32	interface BProfile {
33	  id: string;
34	  config_id: string;
35	  name: string;
36	  case_weights: Record<string, number>;
37	  brand_multipliers: Record<string, number>;
38	  cost_multipliers: Record<string, number>;
39	  is_default: boolean;
40	}
41	interface BSignal {
42	  id: string;
43	  record_id: string;
44	  case_id: string | null;
45	  kind: Signal["kind"];
46	  severity: Signal["severity"] | null;
47	  summary: string;
48	  quote: string;
49	  quote_en: string | null;
50	  market: string;
51	  vehicle: string | null;
52	  vehicle_role: Signal["vehicleRole"] | null;
53	  evidence_role: string | null;
54	  powertrain: string | null;
55	  reach: number | null;
56	  reach_unit: string | null;
57	  aspect_group: Signal["aspectGroup"];
58	  car_area: string[] | null;
59	  published_at: string | null;
60	  topic_id: string | null;
61	  topic: string | null;
62	  source_id: string | null;
63	  content_type: string | null;
64	  url: string | null;
65	  record_title: string | null;
66	}
67	
68	// ---------- context ----------
69	function who(user: User): Persona & { userId: string } {
70	  const p = persona(user.id);
71	  if (!p) throw new ApiError(401, `No backend user for persona ${user.id}`);
72	  return { ...p, userId: user.id };
73	}
74	
75	const get = <T>(user: User, path: string, query?: Record<string, QueryValue>) => backend<T>(who(user).backendUserId, "GET", path, { query });
76	
77	async function write<T>(user: User, method: "POST" | "PUT" | "PATCH", path: string, body?: unknown) {
78	  const out = await backend<T>(who(user).backendUserId, method, path, { body });
79	  invalidateCache();
80	  return out;
81	}
82	
83	const configs = (user: User) => cached("configs", 60_000, () => get<BConfig[]>(user, "/configs"));
84	
85	/** The persona's active config and weight profile (sidecar choice, else the persona default). */
86	export async function activeConfig(user: User): Promise<{ config: BConfig; profileId: string }> {
87	  const p = who(user);
88	  const all = await configs(user);
89	  const choice = sidecar().workspaces[user.id] ?? {};
90	  const config = all.find((c) => c.id === choice.configId) ?? all.find((c) => c.name === p.config);
91	  if (!config) throw new ApiError(404, `Config ${p.config} not found in the backend`);
92	  const profile = config.profiles.find((x) => x.id === choice.profileId) ?? config.profiles.find((x) => x.is_default) ?? config.profiles[0];
93	  if (!profile) throw new ApiError(404, `Config ${config.name} has no weight profile`);
94	  return { config, profileId: profile.id };
95	}
96	
97	function profileFromBackend(p: BProfile): WeightProfile {
98	  return {
99	    id: p.id,
100	    name: p.name,
101	    description: `Weight profile of config ${p.config_id}`,
102	    ownerId: null,
103	    isDefault: p.is_default,
104	    weights: weightsFromBackend(p.case_weights),
105	    costMultiplier: { S: p.cost_multipliers.S ?? 1, M: p.cost_multipliers.M ?? 0.85, L: p.cost_multipliers.L ?? 0.7 },
106	  };
107	}
108	
109	async function profilesOf(user: User, configId: string): Promise<BProfile[]> {
110	  const cfg = await cached(`config:${configId}`, 30_000, () => get<{ profiles: BProfile[] }>(user, `/configs/${configId}`));
111	  return cfg.profiles;
112	}
113	
114	function workspaceOf(user: User, config: BConfig, profileId: string): Workspace {
115	  const market = marketFromBackend(config.market);
116	  return {
117	    id: `ws-${user.id}`,
118	    userId: user.id,
119	    series: config.vehicle as Workspace["series"],
120	    region: market === "CN" ? "CN" : "RoW",
121	    projectType: "new_gen", // rejected option in CLAUDE.md; hidden on real data
122	    weightProfileId: profileId,
123	    sourceFilter: { excludeSocial: false, ownersOnly: false, minTrust: "E" },
124	    watchlist: { competitors: [], topics: [], domains: [], languages: [] },
125	  };
126	}
127	
128	// ---------- mapping ----------
129	function agentOfRun(name: string): Agent {
130	  if (name.includes("competitor")) return "competitor";
131	  if (name.includes("trend")) return "trends";
132	  if (name.includes("innovation")) return "innovation_scout";
133	  if (name.startsWith("seed") || name.includes("bmw")) return "bmw_data";
134	  return "customer_public";
135	}
136	
137	export function signalFromBackend(s: BSignal, series: Signal["series"]): Signal {
138	  return {
139	    id: s.id,
140	    kind: s.kind,
141	    severity: s.severity ?? "none",
142	    agent: agentFromBackend(s.evidence_role, s.source_id, s.kind),
143	    sourceType: sourceTypeFromBackend(s.source_id, s.content_type),
144	    sourceName: s.record_title ?? s.source_id ?? "source",
145	    trust: trustFromBackend(s.source_id, s.content_type),
146	    url: s.url ?? undefined,
147	    recordRef: s.record_id,
148	    publishedAt: s.published_at ?? "",
149	    fetchedAt: s.published_at ?? "",
150	    series: (s.vehicle as Signal["series"]) ?? series,
151	    vehicleRole: s.vehicle_role ?? "unknown",
152	    powertrain: powertrainFromBackend(s.powertrain),
153	    market: marketFromBackend(s.market),
154	    marketBasis: s.market && s.market !== "unknown" ? "stated" : "unknown",
155	    carArea: (s.car_area?.[0] ?? "quality_materials") as Signal["carArea"],
156	    topicId: s.topic_id,
157	    aspectGroup: s.aspect_group,
158	    featureHint: s.topic ?? "",
159	    summary: s.summary,
160	    quote: s.quote,
161	    quoteEn: s.quote_en ?? undefined,
162	    language: s.quote_en ? "other" : "en",
163	    audience: s.evidence_role === "bmw_customer" ? "owner" : s.content_type === "expert" ? "reviewer" : "public",
164	    reach: s.reach ?? undefined,
165	    reachUnit: s.reach_unit === "views" || s.reach_unit === "upvotes" || s.reach_unit === "likes" ? s.reach_unit : undefined,
166	    caseId: s.case_id,
167	    status: s.case_id ? "clustered" : "unclustered",
168	    synthetic: false,
169	  };
170	}
171	
172	const NOTIFICATION_KIND: Record<string, Notification["kind"]> = {
173	  case_opened: "new_signals",
174	  new_evidence: "new_signals",
175	  market_conflict: "alert",
176	  run_failed: "alert",
177	  candidate_feature: "alert",
178	  new_competitor: "alert",
179	  requirement_generated: "new_signals",
180	};
181	
182	// ---------- handlers ----------
183	export const backendHandlers: Partial<Handlers> = {
184	  // Identity
185	  me: async ({ user }) => {
186	    const { config, profileId } = await activeConfig(user);
187	    const profiles = await profilesOf(user, config.id);
188	    const profile = profiles.find((p) => p.id === profileId) ?? profiles[0];
189	    return { user, workspace: workspaceOf(user, config, profileId), weightProfile: profileFromBackend(profile) };
190	  },
191	  users: () => personaUsers(),
192	  updateWorkspace: async ({ user, body }) => {
193	    const { config, profileId } = await activeConfig(user);
194	    const s = sidecar();
195	    const before = { ...s.workspaces[user.id] };
196	    let next = { configId: config.id, profileId };
197	    if (body.series && body.series !== config.vehicle) {
198	      const market = config.market;
199	      const all = await configs(user);
200	      const other = all.find((c) => c.vehicle === body.series && c.market === market) ?? all.find((c) => c.vehicle === body.series);
201	      if (!other) throw new ApiError(404, `No config for ${body.series}`);
202	      next = { configId: other.id, profileId: (other.profiles.find((p) => p.is_default) ?? other.profiles[0]).id };
203	    }
204	    if (body.weightProfileId) next.profileId = body.weightProfileId;
205	    s.workspaces[user.id] = next;
206	    saveSidecar();
207	    sidecarAudit({ actorId: user.id, action: "workspace.updated", objectType: "workspace", objectId: `ws-${user.id}`, before, after: next });
208	    const fresh = await activeConfig(user);
209	    return workspaceOf(user, fresh.config, fresh.profileId);
210	  },
211	
212	  // Signals and agents
213	  signals: async ({ user, query }) => {
214	    const { config } = await activeConfig(user);
215	    const series = (query.series ?? config.vehicle) as Signal["series"];
216	    const res = await get<{ total: number; items: BSignal[] }>(user, "/signals", {
217	      vehicle: query.caseId ? undefined : series,
218	      case_id: query.caseId,
219	      market: query.market ? marketToBackend(query.market) : undefined,
220	      kind: query.kind,
221	      limit: Math.min(query.limit ?? 500, 500),
222	    });
223	    let items = res.items.map((s) => signalFromBackend(s, series));
224	    if (query.agent) items = items.filter((s) => s.agent === query.agent);
225	    if (query.status) items = items.filter((s) => s.status === query.status);
226	    if (query.q) {
227	      const q = query.q.toLowerCase();
228	      items = items.filter((s) => s.summary.toLowerCase().includes(q) || s.quote.toLowerCase().includes(q));
229	    }
230	    return items;
231	  },
232	  clusters: () => [],
233	  agentRuns: async ({ user }) => {
234	    const { config } = await activeConfig(user);
235	    const runs = await get<
236	      { id: string; agent: string; mode: string; status: string; started_at: string; ended_at: string | null; signals_valid: number | null; signals_quarantined: number | null; llm_cost_usd: number | null; error: string | null }[]
237	    >(user, "/runs", { limit: 50 });
238	    return runs.map(
239	      (r): AgentRun => ({
240	        id: r.id,
241	        agent: agentOfRun(r.agent),
242	        series: config.vehicle as AgentRun["series"],
243	        startedAt: r.started_at,
244	        endedAt: r.ended_at ?? r.started_at,
245	        status: r.status === "failed" ? "failed" : r.status === "ok" || r.status === "done" || r.status === "success" ? "ok" : "partial",
246	        valid: r.signals_valid ?? 0,
247	        rejected: r.signals_quarantined ?? 0,
248	        newSignals: r.signals_valid ?? 0,
249	        llmCostUsd: Number(r.llm_cost_usd ?? 0),
250	        note: r.error ?? `${r.agent} (${r.mode})`,
251	      }),
252	    );
253	  },
254	  refresh: () => {
255	    throw new ApiError(501, "Fetch runs are started by the daily worker on the server, not from the UI. See the runs list for the latest results.");
256	  },
257	  quarantine: async ({ user }) => {
258	    const res = await get<{ items: { id: string; record_id: string; reject_reason: string; kind: string; summary: string | null; quote: string | null; agent: string | null; created_at: string }[] }>(
259	      user,
260	      "/quarantine",
261	      { limit: 200 },
262	    );
263	    return res.items.map(
264	      (q): QuarantineItem => ({
265	        id: q.id,
266	        agent: agentOfRun(q.agent ?? ""),
267	        sourceName: q.record_id,
268	        snippet: q.quote ?? q.summary ?? "",
269	        reason: q.reject_reason,
270	        at: q.created_at,
271	      }),
272	    );
273	  },
274	  taxonomy: async ({ user }) => {
275	    const t = await cached("taxonomy", 600_000, () =>
276	      get<{ car_areas: { code: string; name: string; description: string }[]; aspect_groups: { code: string; description: string }[]; topics: { topic_id: string; name: string; car_area: string; hint: string | null; taxonomy_version: string }[] }>(
277	        user,
278	        "/taxonomy",
279	      ),
280	    );
281	    const out: TaxonomyResponse = {
282	      version: t.topics[0]?.taxonomy_version ?? "backend",
283	      carAreas: t.car_areas.map((a) => ({ id: a.code as TaxonomyResponse["carAreas"][number]["id"], label: a.name, description: a.description })),
284	      topics: t.topics.map((x) => ({ id: x.topic_id, label: x.name, shortLabel: x.name.split(",")[0].trim(), carArea: x.car_area as TaxonomyResponse["carAreas"][number]["id"], hint: x.hint })),
285	      aspectGroups: t.aspect_groups.map((a) => ({ id: a.code as TaxonomyResponse["aspectGroups"][number]["id"], description: a.description })),
286	    };
287	    return out;
288	  },
289	
290	  // Scoring profiles
291	  weightProfiles: async ({ user }) => {
292	    const { config } = await activeConfig(user);
293	    return (await profilesOf(user, config.id)).map(profileFromBackend);
294	  },
295	  saveWeightProfile: async ({ user, params, body }) => {
296	    const { config } = await activeConfig(user);
297	    const current = (await profilesOf(user, config.id)).find((p) => p.id === params.id);
298	    if (!current) throw new ApiError(404, "Weight profile not found in your config");
299	    const p = await write<BProfile>(user, "PATCH", `/profiles/${params.id}`, {
300	      name: body.name,
301	      case_weights: body.weights ? weightsToBackend(body.weights, current.case_weights) : undefined,
302	      cost_multipliers: body.costMultiplier,
303	      is_default: body.isDefault,
304	      rationale: "Saved in the weights panel",
305	    });
306	    return profileFromBackend(p);
307	  },
308	  createWeightProfile: async ({ user, body }) => {
309	    const { config, profileId } = await activeConfig(user);
310	    const base = (await profilesOf(user, config.id)).find((p) => p.id === profileId);
311	    const p = await write<BProfile>(user, "POST", `/configs/${config.id}/profiles`, {
312	      name: body.name,
313	      case_weights: weightsToBackend(body.weights, base?.case_weights ?? {}),
314	      cost_multipliers: body.costMultiplier,
315	      rationale: body.description || "Created in the weights panel",
316	    });
317	    return profileFromBackend(p);
318	  },
319	
320	  // Inbox
321	  notifications: async ({ user }) => {
322	    const rows = await get<{ id: string; type: string; object_type: string; object_id: string; message: string; created_at: string; read: boolean }[]>(user, "/notifications", { limit: 100 });
323	    return rows.map(
324	      (n): Notification => ({
325	        id: n.id,
326	        userId: user.id,
327	        kind: NOTIFICATION_KIND[n.type] ?? "alert",
328	        title: n.type.replaceAll("_", " "),
329	        body: n.message,
330	        link: n.object_type === "case" ? `/cases/${n.object_id}` : n.object_type === "requirement" ? `/requirements/${n.object_id}` : "/radar",
331	        read: n.read,
332	        createdAt: n.created_at,
333	      }),
334	    );
335	  },
336	  readNotifications: async ({ user, body }) => {
337	    const ids = body.ids ?? (await get<{ id: string }[]>(user, "/notifications", { unread: true, limit: 500 })).map((n) => n.id);
338	    for (const id of ids) await write(user, "POST", `/notifications/${id}/read`);
339	    return { ok: true as const };
340	  },
341	
342	  // Oversight: reset only clears the sidecar, never the backend
343	  reset: () => {
344	    resetSidecar();
345	    invalidateCache();
346	    return { ok: true as const };
347	  },
348	};
