S="/c/Users/pc/AppData/Local/Temp/claude/C--Users-pc-OneDrive-Bureau-ehl-final-bmw-product-management-challenge/997b0ee5-24b0-4a4b-b583-69eca64bae6f/scratchpad/main"; cd "$S/web" && cat > "$S/../ep.mjs" <<'EOF'
import fs from "fs"; import path from "path";
const root = process.argv[2];
const api = fs.readFileSync(root+"/src/contracts/api.ts","utf8");
const body = api.slice(api.indexOf("export const endpoints = {"));
const contract = [...body.matchAll(/^  ([a-zA-Z]+): ep\(\{\s*(?:\n\s*)?method: "(\w+)",\s*(?:\n\s*)?path: "([^"]+)"/gm)].map(m=>({name:m[1],method:m[2],path:m[3]}));
const names = contract.map(c=>c.name);
const keysOf = (file, startMarker) => { const t = fs.readFileSync(file,"utf8"); const s = t.slice(t.indexOf(startMarker)); return new Set([...s.matchAll(/^  ([a-zA-Z]+): (?:async )?\(/gm)].map(m=>m[1]).concat([...s.matchAll(/^  ([a-zA-Z]+),$/gm)].map(m=>m[1]))); };
const mock = keysOf(root+"/src/mock/handlers.ts","export const handlers");
const be = keysOf(root+"/src/backend/handlers.ts","export const backendHandlers");
const used = new Map();
const walk = d => { for (const f of fs.readdirSync(d,{withFileTypes:true})) { const p = path.join(d,f.name); if (f.isDirectory()) { if (!/node_modules|mock|backend$|contracts/.test(p)) walk(p);} else if (/\.tsx?$/.test(f.name)) { const t = fs.readFileSync(p,"utf8"); for (const m of t.matchAll(/(?:useApi|useApiMutation|api)\(\s*"([a-zA-Z]+)"/g)) { if(!used.has(m[1])) used.set(m[1],[]); used.get(m[1]).push(path.relative(root,p)); } } } };
walk(root+"/src");
console.log("contract",names.length,"mock",mock.size,"backend",be.size,"usedByUI",used.size);
console.log("\nUSED BY UI BUT NOT IN CONTRACT:", [...used.keys()].filter(n=>!names.includes(n)));
console.log("\nIN CONTRACT, NO MOCK HANDLER:", names.filter(n=>!mock.has(n)));
console.log("\nBACKEND HANDLER NOT IN CONTRACT:", [...be].filter(n=>!names.includes(n)));
console.log("\nMOCK-ONLY in backend mode (no adapter handler):"); for (const c of contract) if(!be.has(c.name)) console.log("  ",c.name.padEnd(26),c.method.padEnd(6),c.path.padEnd(40), used.has(c.name)?"UI":"(unused by UI)");
console.log("\nCONTRACT ENDPOINTS NOT USED BY UI:", names.filter(n=>!used.has(n)));
EOF
node "$S/../ep.mjs" "$S/web"

