131	async function loadCase(user: User, id: string, c?: Ctx) {
132	  const x = c ?? (await ctx(user));
133	  const page = await cached(`case:${id}`, 5_000, () => get(user, `/cases/${encodeURIComponent(id)}`));
134	  const vehicles = (page.vehicles as Row[]).map((v) => v.vehicle);
135	  const vehicle = vehicles.includes(x.vehicle) ? x.vehicle : (vehicles[0] ?? x.vehicle);
136	  const row = rowFromPage(page, vehicle, x.profileId);
137	  const merged = (page.lineage as Row[]).find((l) => l.op === "merge" && l.from_case === id);
138	  const pmInputs = [
139	    ...(page.stances as Row[]).map((s) => ({ kind: "note" as const, label: `${x.all.find((u) => u.id === s.author_id)?.name ?? "A PM"}'s context`, detail: [s.ambition && `ambition ${s.ambition}`, ...(s.evidence_takes ?? []).map((t: Row) => `${t.effect}: ${t.text}`), ...(s.inside ?? []).map((i: Row) => i.text)].filter(Boolean).join(" · ") || "No changes to the product specs", at: String(s.updated_at), ref: `stance-${s.author_id}` })),
140	    ...(page.meeting_notes as Row[]).map((n) => ({ kind: "meeting" as const, label: n.title, detail: `${(n.attendees ?? []).length} attendees`, at: String(n.created_at), ref: n.id })),
141	    ...(page.questions as Row[]).filter((q) => q.status === "answered").map((q) => ({ kind: "answer" as const, label: `${q.addressee} answered`, detail: q.answer ?? "", at: String(q.answered_at), ref: q.id })),
142	    ...(page.proposals as Row[]).filter((p) => p.status === "accepted").map((p) => ({ kind: "diff" as const, label: "AI proposal accepted", detail: p.summary, at: String(p.decided_at), ref: p.id })),
143	  ];
144	  const mapped = caseFromBackend(row, x.owner(vehicle), {
145	    stances: (page.stances as Row[]).map(stanceFromBackend),
146	    mergedInto: merged?.to_case ?? null,
147	    context: {
148	      preset: [
149	        { kind: "baseline", label: "Today's equipment", detail: "", ref: "option-list" },
150	        ...(page.decisions as Row[]).slice(0, 5).map((d) => ({ kind: "past_decision" as const, label: `${d.action}${d.vehicle ? ` (${d.vehicle})` : ""}`, detail: d.rationale ?? "", at: String(d.created_at) })),
151	      ],
152	      pmInputs,
153	    },
154	  });
155	  mapped.context.preset[0].detail = mapped.figures.equipmentToday;
156	  return { page, row, vehicle: vehicle as Series, case: mapped, x };
157	}
