230	function scoresFrom(profileId: string, weights: Record<FactorKey, number>, cases: Row[], requirements: Row[]): ScoresResponse {
231	  const empty = () => Object.fromEntries(FactorKeys.options.map((f) => [f, 0])) as Record<FactorKey, number>;
232	  return {
233	    profileId,
234	    weights,
235	    cases: cases.map((r) => {
236	      const contributions = empty();
237	      for (const f of FactorKeys.options) {
238	        const b = FACTOR_TO_BACKEND[f];
239	        if (b) contributions[f] = Math.max(0, Math.min(1, Number(r.contributions?.[b] ?? 0)));
240	      }
241	      return { caseId: r.id ?? r.case_id, profileId, score: Number(r.score ?? 0), rank: r.rank, contributions };
242	    }),
243	    requirements: requirements.map((r) => ({ requirementId: r.id ?? r.requirement_id, score: Number(r.rank_score ?? r.score ?? 0), rank: r.rank })),
244	  };
245	}
