269	async function runCheck(user: User, r: Requirement, trigger: string, x: Ctx): Promise<RequirementCheck> {
270	  const [{ case: c }, siblings, plan] = await Promise.all([loadCase(user, r.caseId, x), reqBoard(user, x.profileId), get(user, `/plans/${r.series}`).then(planFromBackend).catch(() => null)]);
271	  const signals = await caseSignals(user, r.caseId, r.series);
272	  const d = mini({ cases: [{ ...c, signalIds: signals.map((s) => s.id) }], signals, requirements: [r, ...siblings.filter((s) => s.id !== r.id).map((s) => requirementFromBackend(s, x.owner(s.vehicle)))], plans: plan ? [plan] : [] });
273	  const check = ruleCheck(d, r, new Date().toISOString());
274	  const stored = await send(user, "POST", `/requirements/${encodeURIComponent(r.id)}/check`, { engine: check.engine, issues: check.issues, trigger });
275	  return checkFromBackend(stored);
276	}
