8	/**
9	 * One catch-all route that serves the REST contract in src/contracts/api.ts.
10	 * Default: the mock on the in-memory store (synthetic demo data). With
11	 * DATA_SOURCE=backend every endpoint is served by the adapter in src/backend from
12	 * the FastAPI backend (BACKEND_URL); the two data sources are never mixed.
13	 */
14	const USE_BACKEND = process.env.DATA_SOURCE === "backend";
15	/** Who a request without a user is (the login page lists the users before one is picked). */
16	const DEFAULT_BACKEND_USER = process.env.BACKEND_DEFAULT_USER ?? "00000000-0000-4000-8000-000000000001";
17	const isUuid = (v: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
18	
19	const routes = (Object.keys(endpoints) as EndpointName[]).map((name) => {
20	  const def = endpoints[name];
21	  const keys: string[] = [];
22	  const pattern = new RegExp(
23	    "^" +
24	      def.path.replace(/:[a-zA-Z]+/g, (m) => {
25	        keys.push(m.slice(1));
26	        return "([^/]+)";
27	      }) +
28	      "$",
29	  );
30	  return { name, def, keys, pattern };
31	});
32	
33	function match(method: string, path: string) {
34	  for (const r of routes) {
35	    if (r.def.method !== method) continue;
36	    const m = path.match(r.pattern);
37	    if (m) return { ...r, params: Object.fromEntries(r.keys.map((k, i) => [k, decodeURIComponent(m[i + 1])])) };
38	  }
39	  return null;
40	}
41	
42	async function handle(req: NextRequest, ctx: { params: Promise<{ path: string[] }> }) {
43	  const { path } = await ctx.params;
44	  const route = match(req.method, "/" + path.join("/"));
45	  if (!route) return Response.json({ error: `No endpoint ${req.method} /${path.join("/")}` }, { status: 404 });
46	
47	  try {
48	    let userId = req.headers.get("x-user-id") ?? req.cookies.get("rs_user")?.value ?? "u-lena";
49	    // A cookie left over from the mock (u-lena) is not a backend user: fall back to the default one.
50	    if (USE_BACKEND && !isUuid(userId)) userId = DEFAULT_BACKEND_USER;
51	    const user = (USE_BACKEND ? await backendUsers(userId) : db().users).find((u) => u.id === userId);
52	    if (!user) throw new ApiError(401, `Unknown user ${userId}`);
53	
54	    const def = route.def as { query?: { parse(v: unknown): unknown }; body?: { parse(v: unknown): unknown }; response: { safeParse(v: unknown): { success: boolean; error?: ZodError } } };
55	    const query = def.query ? def.query.parse(Object.fromEntries(req.nextUrl.searchParams)) : {};
56	    let body: unknown = undefined;
57	    if (def.body) {
58	      const text = await req.text();
59	      body = def.body.parse(text ? JSON.parse(text) : {});
60	    }
61	
62	    const handler = (USE_BACKEND ? backendHandlers[route.name] : handlers[route.name]) as (c: unknown) => unknown;
63	    const result = await handler({ params: route.params, query, body, user });
64	
65	    if (process.env.NODE_ENV !== "production") {
66	      const check = def.response.safeParse(result);
67	      if (!check.success) console.error(`[${USE_BACKEND ? "backend" : "mock"}] ${route.name} response breaks the contract:`, check.error?.issues.slice(0, 5));
68	    }
69	    return Response.json(result);
70	  } catch (error) {
71	    if (error instanceof ZodError) return Response.json({ error: "Invalid request", issues: error.issues }, { status: 400 });
72	    if (error instanceof ApiError) return Response.json({ error: error.message }, { status: error.status });
73	    console.error("[mock] unhandled", error);
74	    return Response.json({ error: error instanceof Error ? error.message : "Server error" }, { status: 500 });
75	  }
76	}
