131	/** Backend lifecycle per line (state + workflow + outcome) -> the UI's state and outcome. */
132	export function caseStateFromBackend(cv: Row): { state: Case["state"]; outcome: Case["outcome"] } {
133	  if (cv.state === "observed") return { state: "observed", outcome: null };
134	  if (cv.state === "confirmed") return { state: "decided", outcome: "confirmed" };
135	  if (cv.state === "rejected") return { state: "decided", outcome: cv.outcome === "merged" ? "merged" : "rejected" };
136	  if (cv.outcome) return { state: "decided", outcome: cv.outcome };
137	  return { state: cv.workflow ?? "new", outcome: null };
138	}
