140	function equipmentText(eq: Row | undefined): string {
141	  if (!eq?.listed) return "Not in the option list (German market)";
142	  const n = (xs?: unknown[]) => xs?.length ?? 0;
143	  const parts = [n(eq.standard) && `standard on ${n(eq.standard)} variants`, n(eq.optional) && `optional on ${n(eq.optional)}`, n(eq.absent) && `absent on ${n(eq.absent)}`, eq.removed && "removed vs. predecessor"].filter(Boolean);
144	  const price = eq.option_prices_eur?.length ? `; from ${Math.round(eq.option_prices_eur[0])} EUR` : "";
145	  return `${parts.join(", ") || "listed"}${price} (German option list)`;
146	}
