148	function perMarket(markets: Row, study: Row[]): MarketFigure[] {
149	  return Object.entries(markets ?? {})
150	    .map(([name, m]: [string, any]) => {
151	      const market = marketFromBackend(name);
152	      const total = (m.complaints ?? 0) + (m.wishes ?? 0) + (m.likes ?? 0);
153	      const worst = study.filter((s) => s.market === name).sort((a, b) => Number(a.normalized) - Number(b.normalized))[0];
154	      return {
155	        market,
156	        customers: m.customers ?? 0,
157	        complaints: m.complaints ?? 0,
158	        wishes: m.wishes ?? 0,
159	        likes: m.likes ?? 0,
160	        studyLabel: worst?.attribute,
161	        studyScore: worst ? `${round2(Number(worst.normalized))} of 1 (${worst.sheet})` : undefined,
162	        sentiment: total ? round2(Math.max(-1, Math.min(1, ((m.likes ?? 0) - (m.complaints ?? 0) - 0.5 * (m.wishes ?? 0)) / total))) : 0,
163	      };
164	    })
165	    .filter((m) => m.market !== "unknown" || m.customers > 0)
166	    .sort((a, b) => b.customers - a.customers);
167	}
