169	/**
170	 * One case as a PM sees it for one line. `row` is a board row (GET /cases) or the same
171	 * fields built from the case page (see `rowFromPage`). `ownerFallback` is the line's PM
172	 * when nobody took the case yet.
173	 */
174	export function caseFromBackend(row: Row, ownerFallback: string, extra: Partial<Case> = {}): Case {
175	  const { state, outcome } = caseStateFromBackend(row);
176	  const figures = perMarket(row.markets_full ?? {}, row.study ?? []);
177	  const negative = Object.entries(row.markets_full ?? {}).filter(([, m]: [string, any]) => m.negative_share != null);
178	  const conflictMarkets = negative.filter(([, m]: [string, any]) => m.negative_share >= 0.6 || m.negative_share <= 0.4).map(([name]) => marketFromBackend(name));
179	  const factors = { customers: 0, severity: 0, satisfaction_gap: 0, competitor_gap: 0, market_volume: 0, regression: 0, trend: 0, brand_fit: brandFitFromBackend(row.brand_fit) } as Case["factors"];
180	  for (const [k, v] of Object.entries(row.factors ?? {})) {
181	    const f = factorFromBackend(k);
182	    if (f) factors[f] = Math.max(0, Math.min(1, Number(v) || 0));
183	  }
184	  const sources = row.source_types ?? {};
185	  const offers = (row.competitor_offers ?? []).map((o: Row) => `${o.brand} ${o.model}: ${o.metric} ${o.value ?? o.value_text ?? ""}${o.unit ? ` ${o.unit}` : ""}`.trim());
186	  return {
187	    id: row.id,
188	    title: row.title ?? row.id,
189	    shortTitle: row.short_title || row.topic || row.title || row.id,
190	    summary: row.summary ?? "",
191	    highlights: row.highlights ?? [],
192	    topicId: row.topic_id ?? null,
193	    stances: [],
194	    series: row.vehicle,
195	    relatedSeries: (row.other_vehicles ?? []).filter(isSeries),
196	    scope: row.scope ?? "global",
197	    ownerId: row.owner_id ?? ownerFallback,
198	    coOwnerIds: row.co_owner_ids ?? [],
199	    watcherIds: row.watcher_ids ?? [],
200	    state,
201	    outcome,
202	    outcomeNote: row.outcome_note ?? undefined,
203	    markets: figures.map((m) => m.market).filter((m): m is Market => m !== "unknown"),
204	    carArea: row.car_area,
205	    type: row.case_type ?? "fix_improve",
206	    changeDepth: row.change_depth ?? "part_module",
207	    featureName: row.topic ?? "",
208	    bodyMd: rewriteCitations(row.body_md ?? ""),
209	    bodyVersion: row.body_version ?? 1,
210	    signalIds: [],
211	    figures: {
212	      perMarket: figures,
213	      equipmentToday: equipmentText(row.equipment),
214	      competitorOffer: offers.length ? offers : row.competitor_signals ? [`${row.competitor_signals} competitor signals in the evidence`] : [],
215	      trend: row.trend_signals ? `${row.trend_signals} trend signals` : "",
216	    },
217	    marketConflict: row.market_conflict
218	      ? { note: negative.map(([name, m]: [string, any]) => `${name}: ${Math.round(m.negative_share * 100)}% negative of ${m.customers} customers`).join("; "), markets: conflictMarkets }
219	      : null,
220	    brandFit: {
221	      value: brandFitFromBackend(row.brand_fit),
222	      reason: row.brand_fit_reason ?? (row.brand_fit ? `Tagged "${row.brand_fit}" by ${row.brand_fit_source === "pm" ? "the PM" : "the AI"}.` : "Not assessed yet (scored as neutral)."),
223	      confirmedBy: row.brand_fit_confirmed_by ?? null,
224	    },
225	    factors,
226	    evidenceLevel: sources.bmw_internal ? "high" : Object.keys(sources).length ? "medium" : "assumption",
227	    context: { preset: [], pmInputs: [] },
228	    originCaseId: null,
229	    mergedInto: null,
230	    requirementIds: row.requirement_ids ?? [],
231	    manualRank: row.manual_rank ?? null,
232	    manualRankReason: row.manual_rank_reason ?? undefined,
233	    newSignalCount: row.flag_new_evidence ?? 0,
234	    createdAt: iso(row.created_at),
235	    createdBy: actorId(row.created_by),
236	    updatedAt: iso(row.updated_at ?? row.created_at),
237	    synthetic: false,
238	    ...extra,
239	  };
240	}
