312	  if (p.description !== undefined) out.description = p.description;
313	  if (p.descriptionParts !== undefined) out.description_parts = p.descriptionParts;
314	  if (p.marketScope !== undefined) out.market_scope = p.marketScope;
315	  if (p.releaseTarget !== undefined) out.release_target = releaseToBackend(p.releaseTarget);
316	  if (p.changeDepth !== undefined) out.change_depth = p.changeDepth;
317	  if (p.metrics !== undefined) out.metrics = p.metrics;
318	  if (p.acceptanceCriteria !== undefined) out.acceptance_criteria = p.acceptanceCriteria;
319	  if (p.assumptions !== undefined) out.assumptions = p.assumptions;
320	  if (p.evidenceLevel !== undefined) out.evidence_level = evidenceToBackend(p.evidenceLevel);
321	  if (p.cost !== undefined) {
322	    out.cost_size = p.cost.size;
323	    out.cost_band = p.cost.eurBand;
324	    out.cost_source = p.cost.source;
325	    out.cost_note = p.cost.note;
326	  }
327	  if (p.provenance !== undefined) out.provenance = p.provenance;
328	  if (p.shapeAnswers !== undefined) out.shape_answers = p.shapeAnswers;
329	  return out;
