"""People and their workspace: who the PMs are, which config (vehicle x market) and
weight profile each one works with, and personal notifications."""

from __future__ import annotations

import uuid

from app import audit

USER_COLUMNS = ("id, name, role, vehicles, handle, pm_role, title, initials, color, region, attribute_scope,"
                " synthetic")
WORKSPACE_FIELDS = {"config_id", "weight_profile_id", "source_filter", "watchlist"}
REGION_MARKET = {"CN": "China"}


def users(conn) -> list[dict]:
    return conn.execute(f"select {USER_COLUMNS} from app_user order by pm_role nulls last, name").fetchall()


def head(conn) -> dict | None:
    """The head of product line (signs off, resolves escalations)."""
    return conn.execute(f"select {USER_COLUMNS} from app_user where pm_role = 'head' order by created_at"
                        " limit 1").fetchone()


def default_owner(conn, vehicle: str, scope: str = "global") -> uuid.UUID | None:
    """The PM of a line for a region: the China PM for scope CN, else the PM of the other markets."""
    row = conn.execute(
        "select id from app_user where role = 'pm' and %s = any(vehicles)"
        " order by (pm_role = 'vehicle_pm') desc nulls last, ((region = 'CN') = %s) desc, created_at limit 1",
        (vehicle, scope == "CN")).fetchone()
    return row["id"] if row else None


def _default_profile(conn, config_id):
    if config_id is None:
        return None
    row = conn.execute("select id from weight_profile where config_id = %s order by is_default desc, name limit 1",
                       (config_id,)).fetchone()
    return row["id"] if row else None


def workspace(conn, user) -> dict:
    """The stored workspace, or the default one: the user's line in their region's
    market (China for the China PM, else the market with the largest 2030 volume)."""
    row = conn.execute("select * from workspace where user_id = %s", (user.id,)).fetchone()
    if row and row["config_id"] and conn.execute("select 1 from config where id = %s and active",
                                                 (row["config_id"],)).fetchone():
        if not row["weight_profile_id"]:
            row["weight_profile_id"] = _default_profile(conn, row["config_id"])
        return row
    vehicles = list(user.vehicles)
    cfg = conn.execute(
        "select c.id from config c left join sales_volume s on s.vehicle = c.vehicle and s.market = c.market"
        " and s.year = 2030 where c.active and (cardinality(%s::text[]) = 0 or c.vehicle = any(%s::text[]))"
        " order by (c.market = %s) desc, s.units desc nulls last, c.name limit 1",
        (vehicles, vehicles, REGION_MARKET.get(user.region, ""))).fetchone()
    config_id = cfg["id"] if cfg else None
    base = row or {"user_id": uuid.UUID(user.id),
                   "source_filter": {"excludeSocial": False, "ownersOnly": False, "minTrust": "E"},
                   "watchlist": {"competitors": [], "topics": [], "domains": [], "languages": []}}
    return {**base, "config_id": config_id, "weight_profile_id": _default_profile(conn, config_id)}


def update_workspace(conn, user, changes: dict, *, request_id=None) -> dict:
    changes = {k: v for k, v in changes.items() if v is not None}
    unknown = set(changes) - WORKSPACE_FIELDS
    if unknown:
        raise ValueError(f"workspace fields {sorted(unknown)} cannot be changed")
    current = workspace(conn, user)
    config_id = changes.get("config_id", current["config_id"])
    if "config_id" in changes and "weight_profile_id" not in changes:
        changes["weight_profile_id"] = _default_profile(conn, config_id)
    profile_id = changes.get("weight_profile_id", current["weight_profile_id"])
    if profile_id and not conn.execute("select 1 from weight_profile where id = %s and config_id = %s",
                                       (profile_id, config_id)).fetchone():
        raise ValueError("the weight profile does not belong to the config")
    if conn.execute("select 1 from workspace where user_id = %s", (user.id,)).fetchone():
        audit.update(conn, "workspace", {"user_id": uuid.UUID(user.id)},
                     {**changes, "config_id": config_id, "weight_profile_id": profile_id}, actor=user.actor,
                     rationale="workspace updated", request_id=request_id)
    else:
        audit.insert(conn, "workspace", {"user_id": uuid.UUID(user.id), "config_id": config_id,
                                         "weight_profile_id": profile_id,
                                         **{k: v for k, v in changes.items() if k in ("source_filter", "watchlist")}},
                     actor=user.actor, key="user_id", rationale="workspace created", request_id=request_id)
    return workspace(conn, user)


def notify(conn, user_id, kind: str, title: str, message: str, link: str, *, actor: str,
           object_type: str | None = None, object_id: str | None = None, vehicle: str | None = None,
           request_id=None) -> None:
    """One person's inbox item (the bell); never sent to the person who caused it."""
    if user_id is None or actor.endswith(f":{user_id}"):
        return
    audit.insert(conn, "notification", {"type": kind, "user_id": user_id, "title": title, "message": message,
                                        "link": link, "actor": actor, "object_type": object_type,
                                        "object_id": object_id, "vehicle": vehicle},
                 actor=actor, request_id=request_id)
"""AI proposals: the AI never edits, it proposes; a person accepts or rejects.

A proposal row records what was proposed and what the person decided. Accepting
applies the change through the normal audited write path of its object: the
caller (API route or UI adapter) does that first, then records the decision
here. The one kind applied here is a page diff of the RAG agent, which carries
its own stale-save check.
"""

from __future__ import annotations

import datetime as dt
import uuid

from app import audit

FIELDS = ("object_type", "object_id", "source", "kind", "summary", "changes", "question_id", "citations",
          "chat_message_id", "meeting_note_id")


def create(conn, data: dict, *, agent: str, requested_by: str | None = None, request_id=None) -> dict:
    """``agent`` is the proposing agent's name (note_extractor, drafter, monitor, ...)."""
    row = {k: data[k] for k in FIELDS if data.get(k) is not None}
    return audit.insert(conn, "proposal", {**row, "created_by": f"agent:{agent}"}, actor=f"agent:{agent}",
                        rationale=data.get("summary") if not requested_by else
                        f"{data.get('summary')} (asked by {requested_by})", request_id=request_id)


def from_chat_edit(conn, message: dict, *, request_id=None) -> dict:
    """The RAG agent proposed a page edit: the same proposal, decided the same way as every other."""
    diff = message["proposed_diff"]
    return create(conn, {
        "object_type": message["object_type"], "object_id": message["object_id"], "source": "chat", "kind": "body",
        "summary": diff.get("reason") or "Page edit proposed by the assistant",
        "changes": [{"field": "bodyMd", "before": None, "after": diff.get("body_md")}],
        "chat_message_id": message["id"]}, agent="rag", request_id=request_id)


def listing(conn, object_type: str | None = None, object_ids: list[str] | None = None,
            status: str | None = None) -> list[dict]:
    return conn.execute(
        "select * from proposal where (%(t)s::text is null or object_type = %(t)s)"
        " and (%(ids)s::text[] is null or object_id = any(%(ids)s::text[]))"
        " and (%(s)s::text is null or status = %(s)s) order by created_at",
        {"t": object_type, "ids": object_ids, "s": status}).fetchall()


def decide(conn, proposal_id: str, user, accept: bool, note: str | None = None, *, request_id=None) -> dict:
    from app.rag import agent

    p = audit.fetch_for_update(conn, "proposal", {"id": proposal_id})
    if p["status"] != "pending":
        raise ValueError("the proposal is already decided")
    if p["chat_message_id"]:
        # The page edit is applied with its stale-save check; decide_edit records the decision on this row too.
        agent.decide_edit(conn, str(p["chat_message_id"]), accept, actor=user.actor, request_id=request_id)
        return conn.execute("select * from proposal where id = %s", (proposal_id,)).fetchone()
    return audit.update(conn, "proposal", {"id": proposal_id}, {
        "status": "accepted" if accept else "rejected", "decided_by": uuid.UUID(user.id),
        "decided_at": dt.datetime.now(dt.timezone.utc), "decision_note": note}, actor=user.actor,
        rationale=note or p["summary"], action="accept" if accept else "reject", request_id=request_id)
"""The vehicle plan: the successor of a line, feature by feature. A feature is a
topic of the fixed taxonomy. Today's equipment comes from the option lists
(``vehicle_feature``), the linked requirements from the cases of the topic; only
the PM's decisions (keep / new / improve / remove, release, protected, note) are
stored, in ``planned_feature``."""

from __future__ import annotations

from app import audit
from app.collab.briefs import Forbidden

RANK = {"standard": 3, "optional": 2, "removed": 1, "absent": 0}
PLANNED = ("signed_off", "planned", "exported")


def ensure_plan(conn, vehicle: str) -> dict:
    row = conn.execute("select * from vehicle_plan where vehicle = %s", (vehicle,)).fetchone()
    if row:
        return row
    v = conn.execute("select code, series from vehicle where code = %s and is_current", (vehicle,)).fetchone()
    if v is None:
        raise audit.NotFound(f"no current vehicle line {vehicle}")
    owners = [r["id"] for r in conn.execute(
        "select id from app_user where role = 'pm' and pm_role = 'vehicle_pm' and %s = any(vehicles)"
        " order by created_at", (vehicle,)).fetchall()]
    return audit.insert(conn, "vehicle_plan", {"vehicle": vehicle, "successor_name": f"Successor of the {v['series']}"
                                               f" ({vehicle})", "owner_ids": owners},
                        actor="system", key="vehicle", rationale="vehicle plan opened")


def _today(rows: list[dict]) -> tuple[str, str]:
    """Best availability over the variants, and a one-line detail."""
    if not rows:
        return "absent", "Not in the option list (DE)"
    by_variant: dict[str, str] = {}
    for r in rows:
        if RANK[r["availability"]] > RANK.get(by_variant.get(r["variant"], ""), -1):
            by_variant[r["variant"]] = r["availability"]
    counts = {a: sum(1 for v in by_variant.values() if v == a) for a in RANK}
    best = max(by_variant.values(), key=RANK.get)
    prices = sorted({float(r["price_eur"]) for r in rows if r["price_eur"]})
    parts = [f"{a} on {n} variant{'s' if n != 1 else ''}" for a, n in counts.items() if n]
    return best, ", ".join(parts) + (f"; from {prices[0]:.0f} EUR" if prices else "") + " (DE option list)"


def plan(conn, vehicle: str) -> dict:
    head = ensure_plan(conn, vehicle)
    equipment: dict = {}
    for r in conn.execute("select feature_id, variant, availability, price_eur from vehicle_feature"
                          " where vehicle = %s and feature_id is not null", (vehicle,)).fetchall():
        equipment.setdefault(r["feature_id"], []).append(r)
    decisions = {r["feature_id"]: r for r in conn.execute(
        "select * from planned_feature where vehicle = %s", (vehicle,)).fetchall()}
    reqs: dict = {}
    for r in conn.execute(
            "select r.id, r.status, r.release_target, c.feature_id from requirement r join case_item c"
            " on c.id = r.case_id where r.vehicle = %s and r.status not in ('rejected', 'deleted') order by r.id",
            (vehicle,)).fetchall():
        reqs.setdefault(r["feature_id"], []).append(r)
    ids = set(equipment) | set(decisions) | set(reqs)
    features = []
    for f in conn.execute("select id, topic_id, name, car_area from feature where id = any(%s) and car_area is not"
                          " null order by car_area, name", (list(ids),)).fetchall():
        today, detail = _today(equipment.get(f["id"], []))
        d = decisions.get(f["id"]) or {}
        linked = reqs.get(f["id"], [])
        features.append({
            "id": f["topic_id"], "car_area": f["car_area"], "name": f["name"], "today": today,
            "today_detail": detail,
            "action": d.get("action") or ("new" if today == "absent" and linked else "improve" if linked else "keep"),
            "release": d.get("release") or (linked[0]["release_target"] if linked else None) or "next_gen",
            "protected": bool(d.get("is_protected")), "note": d.get("note") or "",
            "requirement_ids": [r["id"] for r in linked], "decided": bool(d),
        })
    return {**head, "features": features}


def _feature(conn, topic_id: str) -> dict:
    f = conn.execute("select id, name from feature where topic_id = %s", (topic_id,)).fetchone()
    if f is None:
        raise audit.NotFound(f"unknown topic {topic_id}")
    return f


def patch_feature(conn, vehicle: str, topic_id: str, user, changes: dict, rationale: str, *, request_id=None) -> dict:
    head = ensure_plan(conn, vehicle)
    if not user.is_head and user.id not in {str(o) for o in head["owner_ids"]} and not (
            user.role == "pm" and user.pm_role != "attribute_pm" and vehicle in user.vehicles):
        raise Forbidden("only the PMs of the series edit the vehicle plan")
    if not rationale:
        raise ValueError("a plan change needs a reason")
    f = _feature(conn, topic_id)
    changes = {k: v for k, v in changes.items() if k in ("action", "release", "is_protected", "note")
               and v is not None}
    key = {"vehicle": vehicle, "feature_id": f["id"]}
    if conn.execute("select 1 from planned_feature where vehicle = %s and feature_id = %s",
                    (vehicle, f["id"])).fetchone():
        return audit.update(conn, "planned_feature", key, changes, actor=user.actor, rationale=rationale,
                            request_id=request_id)
    current = next((x for x in plan(conn, vehicle)["features"] if x["id"] == topic_id), None)
    base = {"action": current["action"], "release": current["release"]} if current else {}
    return audit.insert(conn, "planned_feature", {**key, **base, **changes}, actor=user.actor,
                        key=("vehicle", "feature_id"), rationale=rationale, request_id=request_id)


def link_requirement(conn, requirement: dict, *, actor: str, request_id=None) -> None:
    """Planning a requirement records the decision on its feature (the topic of its case)."""
    ensure_plan(conn, requirement["vehicle"])
    f = conn.execute("select c.feature_id from case_item c where c.id = %s", (requirement["case_id"],)).fetchone()
    if conn.execute("select 1 from planned_feature where vehicle = %s and feature_id = %s",
                    (requirement["vehicle"], f["feature_id"])).fetchone():
        return
    listed = conn.execute("select 1 from vehicle_feature where vehicle = %s and feature_id = %s and availability in"
                          " ('standard', 'optional') limit 1", (requirement["vehicle"], f["feature_id"])).fetchone()
    audit.insert(conn, "planned_feature", {
        "vehicle": requirement["vehicle"], "feature_id": f["feature_id"], "action": "improve" if listed else "new",
        "release": requirement["release_target"] or "next_gen"}, actor=actor, key=("vehicle", "feature_id"),
        rationale=f"planned with {requirement['id']}", request_id=request_id)
"""PM context layer 1: the series brief. One shared brief per BMW line, plus a
regional overlay per PM that holds only the fields that differ (each with a
reason). ``values`` and ``meta`` are stored in the UI contract's shape."""

from __future__ import annotations

import datetime as dt
import uuid

from app import audit

FIELDS = ("thesis", "targetCustomer", "marketWeights", "changeAmbition", "protectList", "dontFightOn", "givens",
          "costEnvelope")
MARKET_KEY = {"Europe": "EU", "USA": "US", "China": "CN", "Rest of World": "RoW"}


class Forbidden(PermissionError):
    pass


def _now() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def get(conn, brief_id: str) -> dict:
    row = conn.execute("select * from series_brief where id = %s", (brief_id,)).fetchone()
    if row is None:
        raise audit.NotFound(f"brief {brief_id} not found")
    return row


def shared(conn, vehicle: str) -> dict | None:
    return conn.execute("select * from series_brief where vehicle = %s and kind = 'shared'", (vehicle,)).fetchone()


def overlay(conn, vehicle: str, user_id) -> dict | None:
    return conn.execute("select * from series_brief where vehicle = %s and kind = 'overlay' and owner_id = %s",
                        (vehicle, user_id)).fetchone()


def prefill(conn, vehicle: str) -> tuple[dict, dict]:
    """What the data already answers: market weights (2030 sales), the protect list
    (topics customers like most) and the don't-fight-on list (brand profile). The
    PM confirms each; everything else is the PM's own answer."""
    values: dict = {}
    sales = conn.execute("select market, units from sales_volume where vehicle = %s and year = 2030",
                         (vehicle,)).fetchall()
    total = sum(r["units"] or 0 for r in sales)
    if total:
        weights = {k: 0.0 for k in MARKET_KEY.values()}
        for r in sales:
            if r["market"] in MARKET_KEY:
                weights[MARKET_KEY[r["market"]]] = round((r["units"] or 0) / total, 2)
        values["marketWeights"] = weights
    liked = conn.execute(
        "select f.name, count(*) n from signal s join feature f on f.id = s.feature_id"
        " where s.vehicle = %s and s.kind = 'like' and s.validation = 'valid' and s.evidence_role = 'bmw_customer'"
        " group by f.name order by n desc, f.name limit 5", (vehicle,)).fetchall()
    if liked:
        values["protectList"] = [r["name"] for r in liked]
    brand = conn.execute("select do_not from brand_profile order by version desc limit 1").fetchone()
    if brand and brand["do_not"]:
        values["dontFightOn"] = list(brand["do_not"])
    return values, {"marketWeights": "data", "protectList": "data", "dontFightOn": "brand"}


def ensure_shared(conn, vehicle: str, owner_id, *, actor: str = "seed:briefs") -> dict:
    """The shared brief of a line, created once with the data pre-fill (unconfirmed)."""
    row = shared(conn, vehicle)
    if row:
        return row
    values, source = prefill(conn, vehicle)
    at = _now()
    meta = {k: {"source": source[k], "confirmed": False, "updatedAt": at, "updatedBy": str(owner_id)} for k in values}
    return audit.insert(conn, "series_brief", {"id": f"BRIEF-{vehicle}", "vehicle": vehicle, "kind": "shared",
                                               "region": "global", "owner_id": owner_id, "values": values,
                                               "meta": meta},
                        actor=actor, rationale="shared brief pre-filled from sales, liked topics and the brand profile")


def create_overlay(conn, vehicle: str, user, *, request_id=None) -> dict:
    base = shared(conn, vehicle)
    if base is None:
        raise audit.NotFound(f"no shared brief for {vehicle}")
    if user.pm_role != "vehicle_pm" or not user.owns(vehicle):
        raise Forbidden(f"only a PM of the {vehicle} creates a regional overlay")
    if str(base["owner_id"]) == user.id:
        raise ValueError("you own the shared brief; edit it directly")
    existing = overlay(conn, vehicle, user.id)
    if existing:
        return existing
    values, meta = {}, {}
    if user.region == "CN":
        values["marketWeights"] = {"EU": 0, "US": 0, "CN": 1, "RoW": 0}
        meta["marketWeights"] = {"source": "data", "confirmed": False, "updatedAt": _now(), "updatedBy": user.id,
                                 "reason": "China PM: your variants are judged on the Chinese market only."}
    n = conn.execute("select count(*) n from series_brief where vehicle = %s and kind = 'overlay'",
                     (vehicle,)).fetchone()["n"]
    return audit.insert(conn, "series_brief", {
        "id": f"BRIEF-{vehicle}-{user.region}" + (f"-{n + 1}" if n else ""), "vehicle": vehicle, "kind": "overlay",
        "region": user.region, "parent_id": base["id"], "owner_id": uuid.UUID(user.id), "values": values,
        "meta": meta}, actor=user.actor, rationale="regional overlay on the shared brief", request_id=request_id)


def conflicts(base: dict, over: dict) -> list[dict]:
    """Overlay fields that differ from the shared brief."""
    out = []
    for k in FIELDS:
        if k not in over["values"] or over["values"][k] == base["values"].get(k):
            continue
        resolution = (over["meta"].get(k) or {}).get("resolution") or {}
        if resolution.get("status") == "aligned":
            continue
        out.append({"field": k, "overlayId": over["id"], "sharedValue": base["values"].get(k),
                    "overlayValue": over["values"][k], "reason": (over["meta"].get(k) or {}).get("reason", ""),
                    "status": "regional_variant" if resolution.get("status") == "regional_variant" else "open"})
    return out


