import { ZodError } from "zod";
import { endpoints, type EndpointName } from "@/contracts";
import { handlers } from "@/mock/handlers";
import { ApiError, db } from "@/mock/store";

const routes = (Object.keys(endpoints) as EndpointName[]).map((name) => {
  const def = endpoints[name]; const keys: string[] = [];
  const pattern = new RegExp("^" + def.path.replace(/:[a-zA-Z]+/g, (m) => { keys.push(m.slice(1)); return "([^/]+)"; }) + "$");
  return { name, def: def as any, keys, pattern };
});
(globalThis as any).fetch = async (url: string, init: any) => {
  const u = new URL(url); const path = u.pathname.replace(/^\/api/, "");
  const reply = (status: number, json: unknown) => ({ status, ok: status < 400, json: async () => json });
  for (const r of routes) {
    if (r.def.method !== init.method) continue;
    const m = path.match(r.pattern); if (!m) continue;
    try {
      const params = Object.fromEntries(r.keys.map((k, i) => [k, decodeURIComponent(m[i + 1])]));
      const user = db().users.find((x) => x.id === init.headers["x-user-id"]);
      if (!user) throw new ApiError(401, "Unknown user");
      const query = r.def.query ? r.def.query.parse(Object.fromEntries(u.searchParams)) : {};
      const body = r.def.body ? r.def.body.parse(init.body ? JSON.parse(init.body) : {}) : undefined;
      return reply(200, JSON.parse(JSON.stringify(await (handlers as any)[r.name]({ params, query, body, user }))));
    } catch (e: any) {
      if (e instanceof ZodError) return reply(400, { error: "Invalid request", issues: e.issues });
      if (e instanceof ApiError) return reply(e.status, { error: e.message });
      return reply(500, { error: String(e?.stack ?? e) });
    }
  }
  return reply(404, { error: "no endpoint " + path });
};
process.env.API_BASE = "http://x/api";
import("./contract-test");
